    // discretion. If that occurs, the lastIndexOf operation should complete
    // successfully.
    expectedError = Test262Error;
  }

  assert.throws(expectedError, () => {
    array.lastIndexOf(0);
    throw new Test262Error('lastIndexOf completed successfully');
  });
}, null, ["passthrough"]);
