function main(): void {
for (let ctor of ctors) {
  const rab = CreateResizableArrayBuffer(4 * ctor.BYTES_PER_ELEMENT, 8 * ctor.BYTES_PER_ELEMENT);
  const fixedLength = new ctor(rab, 0, 4);
  const fixedLengthWithOffset = new ctor(rab, 2 * ctor.BYTES_PER_ELEMENT, 2);
  const lengthTracking = new ctor(rab, 0);
  const lengthTrackingWithOffset = new ctor(rab, 2 * ctor.BYTES_PER_ELEMENT);

  // Write some data into the array.
  const taWrite = new ctor(rab);
  for (let i = 0; i < taWrite.length; ++i) {
    taWrite[i] = MayNeedBigInt(taWrite, 2 * i);
  }

  // Orig. array: [0, 2, 4, 6]
  //              [0, 2, 4, 6] << fixedLength
  //                    [4, 6] << fixedLengthWithOffset
  //              [0, 2, 4, 6, ...] << lengthTracking
  //                    [4, 6, ...] << lengthTrackingWithOffset

  function MapGathering(array) {
    const values = [];
    function GatherValues(n, ix) {
      assert.sameValue(ix, values.length);
      values.push(n);
      if (typeof n == 'bigint') {
        return n + 1n;
      }
      return n + 1;
    }
    const newValues = array.map(GatherValues);
    for (let i = 0; i < values.length; ++i) {
      if (typeof values[i] == 'bigint') {
        assert.sameValue(values[i] + 1n, newValues[i]);
      } else {
        assert.sameValue(values[i] + 1, newValues[i]);
      }
    }
    return ToNumbers(values);
  }
  assert.compareArray(MapGathering(fixedLength), [
    0,
    2,
    4,
    6
  ]);
  assert.compareArray(MapGathering(fixedLengthWithOffset), [
    4,
    6
  ]);
  assert.compareArray(MapGathering(lengthTracking), [
    0,
    2,
    4,
    6
  ]);
  assert.compareArray(MapGathering(lengthTrackingWithOffset), [
    4,
    6
  ]);

  // Shrink so that fixed length TAs go out of bounds.
  rab.resize(3 * ctor.BYTES_PER_ELEMENT);

  // Orig. array: [0, 2, 4]
  //              [0, 2, 4, ...] << lengthTracking
  //                    [4, ...] << lengthTrackingWithOffset

  assert.throws(TypeError, () => {
    MapGathering(fixedLength);
  });
  assert.throws(TypeError, () => {
    MapGathering(fixedLengthWithOffset);
  });

  assert.compareArray(MapGathering(lengthTracking), [
    0,
    2,
    4
  ]);
  assert.compareArray(MapGathering(lengthTrackingWithOffset), [4]);

  // Shrink so that the TAs with offset go out of bounds.
  rab.resize(1 * ctor.BYTES_PER_ELEMENT);
  assert.throws(TypeError, () => {
    MapGathering(fixedLength);
  });
  assert.throws(TypeError, () => {
    MapGathering(fixedLengthWithOffset);
  });
  assert.throws(TypeError, () => {
    MapGathering(lengthTrackingWithOffset);
  });

  assert.compareArray(MapGathering(lengthTracking), [0]);

  // Shrink to zero.
  rab.resize(0);
  assert.throws(TypeError, () => {
    MapGathering(fixedLength);
  });
  assert.throws(TypeError, () => {
    MapGathering(fixedLengthWithOffset);
  });
  assert.throws(TypeError, () => {
    MapGathering(lengthTrackingWithOffset);
  });

  assert.compareArray(MapGathering(lengthTracking), []);

  // Grow so that all TAs are back in-bounds.
  rab.resize(6 * ctor.BYTES_PER_ELEMENT);
  for (let i = 0; i < 6; ++i) {
    taWrite[i] = MayNeedBigInt(taWrite, 2 * i);
  }

  // Orig. array: [0, 2, 4, 6, 8, 10]
  //              [0, 2, 4, 6] << fixedLength
  //                    [4, 6] << fixedLengthWithOffset
  //              [0, 2, 4, 6, 8, 10, ...] << lengthTracking
  //                    [4, 6, 8, 10, ...] << lengthTrackingWithOffset

  assert.compareArray(MapGathering(fixedLength), [
    0,
    2,
    4,
    6
  ]);
  assert.compareArray(MapGathering(fixedLengthWithOffset), [
    4,
    6
  ]);
  assert.compareArray(MapGathering(lengthTracking), [
    0,
    2,
    4,
    6,
    8,
    10
  ]);
  assert.compareArray(MapGathering(lengthTrackingWithOffset), [
    4,
    6,
    8,
    10
  ]);
}
}
main();

function main(): void {
assert.sameValue(
  typeof TypedArray.prototype.map,
  'function',
  'implements TypedArray.prototype.map'
);

assert.sameValue(
  typeof ArrayBuffer.prototype.resize,
  'function',
  'implements ArrayBuffer.prototype.resize'
);

testWithTypedArrayConstructors(TA => {
  var BPE = TA.BYTES_PER_ELEMENT;
  var ab = new ArrayBuffer(BPE * 4, {maxByteLength: BPE * 5});
  var array = new TA(ab, BPE, 2);

  try {
    ab.resize(BPE * 5);
  } catch (_) {}

  // no error following grow:
  array.map(() => {});

  try {
    ab.resize(BPE * 3);
  } catch (_) {}

  // no error following shrink (within bounds):
  array.map(() => {});

  var expectedError;
  try {
    ab.resize(BPE * 3 - 1);
    // If the preceding "resize" operation is successful, the typed array will
    // be out out of bounds, so the subsequent prototype method should produce
    // a TypeError due to the semantics of ValidateTypedArray.
    expectedError = TypeError;
  } catch (_) {
    // The host is permitted to fail any "resize" operation at its own
    // discretion. If that occurs, the map operation should complete
    // successfully.
    expectedError = Test262Error;
  }

  assert.throws(expectedError, () => {
    array.map(() => {});
    throw new Test262Error('map completed successfully');
  });
}, null, ["passthrough"]);
}
main();

