  const lengthTrackingWithOffset = new ctor(rab, 2 * ctor.BYTES_PER_ELEMENT);

  // Write some data into the array.
  const taWrite = new ctor(rab);
  for (let i = 0; i < 4; ++i) {
    taWrite[i] = MayNeedBigInt(taWrite, i);
  }
  const fixedLengthSlice = fixedLength.slice();
  assert.compareArray(ToNumbers(fixedLengthSlice), [
    0,
    1,
    2,
    3
  ]);
  assert(!fixedLengthSlice.buffer.resizable);
  const fixedLengthWithOffsetSlice = fixedLengthWithOffset.slice();
  assert.compareArray(ToNumbers(fixedLengthWithOffsetSlice), [
    2,
    3
  ]);
  assert(!fixedLengthWithOffsetSlice.buffer.resizable);
  const lengthTrackingSlice = lengthTracking.slice();
  assert.compareArray(ToNumbers(lengthTrackingSlice), [
    0,
    1,
    2,
    3
  ]);
  assert(!lengthTrackingSlice.buffer.resizable);
  const lengthTrackingWithOffsetSlice = lengthTrackingWithOffset.slice();
  assert.compareArray(ToNumbers(lengthTrackingWithOffsetSlice), [
    2,
    3
  ]);
  assert(!lengthTrackingWithOffsetSlice.buffer.resizable);

  // Shrink so that fixed length TAs go out of bounds.
  rab.resize(3 * ctor.BYTES_PER_ELEMENT);
  assert.throws(TypeError, () => {
    fixedLength.slice();
  });
  assert.throws(TypeError, () => {
    fixedLengthWithOffset.slice();
  });
  assert.compareArray(ToNumbers(lengthTracking.slice()), [
    0,
    1,
    2
  ]);
  assert.compareArray(ToNumbers(lengthTrackingWithOffset.slice()), [2]);

  // Shrink so that the TAs with offset go out of bounds.
  rab.resize(1 * ctor.BYTES_PER_ELEMENT);
  assert.throws(TypeError, () => {
    fixedLength.slice();
  });
  assert.throws(TypeError, () => {
    fixedLengthWithOffset.slice();
  });
  assert.compareArray(ToNumbers(lengthTracking.slice()), [0]);
  assert.throws(TypeError, () => {
    lengthTrackingWithOffset.slice();
  });

  // Shrink to zero.
  rab.resize(0);
  assert.throws(TypeError, () => {
    fixedLength.slice();
  });
  assert.throws(TypeError, () => {
    fixedLengthWithOffset.slice();
  });
  assert.compareArray(ToNumbers(lengthTracking.slice()), []);
  assert.throws(TypeError, () => {
    lengthTrackingWithOffset.slice();
  });

  // Verify that the previously created slices aren't affected by the
  // shrinking.
  assert.compareArray(ToNumbers(fixedLengthSlice), [
    0,
    1,
    2,
    3
  ]);
  assert.compareArray(ToNumbers(fixedLengthWithOffsetSlice), [
    2,
    3
  ]);
  assert.compareArray(ToNumbers(lengthTrackingSlice), [
    0,
    1,
    2,
    3
  ]);
  assert.compareArray(ToNumbers(lengthTrackingWithOffsetSlice), [
    2,
    3
  ]);

  // Grow so that all TAs are back in-bounds. New memory is zeroed.
  rab.resize(6 * ctor.BYTES_PER_ELEMENT);
  assert.compareArray(ToNumbers(fixedLength.slice()), [
    0,
    0,
    0,
    0
  ]);
  assert.compareArray(ToNumbers(fixedLengthWithOffset.slice()), [
    0,
    0
  ]);
  assert.compareArray(ToNumbers(lengthTracking.slice()), [
    0,
    0,
    0,
    0,
    0,
    0
  ]);
  assert.compareArray(ToNumbers(lengthTrackingWithOffset.slice()), [
    0,
    0,
    0,
    0
  ]);
}
}
main();

function main(): void {
var N = 4;

for (var TA of typedArrayConstructors) {
  var byteLength = N * TA.BYTES_PER_ELEMENT;
  var buffer = new ArrayBuffer(byteLength, {maxByteLength: byteLength});
  var ta = new TA(buffer);

  for (var startIndex = 0; startIndex <= N; ++startIndex) {
    // Reset typed array and buffer.
    buffer.resize(byteLength);
    ta.fill(1);

    // |start| 
    var start = {
      valueOf() {
        ta.buffer.resize(0);
        return startIndex;
      }
    };

    var sliced = ta.slice(start);

    // Result typed array has the correct length with all elements set to zero.
    assert.compareArray(
      sliced,
      new TA(N - startIndex),
      `${TA.name} with startIndex = ${startIndex}`
    );
  }
}

// Repeat test with different target typed array constructors.
for (var SourceTA of typedArrayConstructors) {
  for (var TargetTA of typedArrayConstructors) {
    var byteLength = N * SourceTA.BYTES_PER_ELEMENT;
    var buffer = new ArrayBuffer(byteLength, {maxByteLength: byteLength});
    var ta = new SourceTA(buffer);

    // Create own "constructor" property to create a different result typed array.
    Object.defineProperty(ta, "constructor", {
      value: TargetTA,
    });

    for (var startIndex = 0; startIndex <= N; ++startIndex) {
      // Reset typed array and buffer.
      buffer.resize(byteLength);
      ta.fill(1);

      var start = {
        valueOf() {
          ta.buffer.resize(0);
          return startIndex;
        }
      };

      var sliced = ta.slice(start);

      // |sliced| is an instance of |TargetTA|.
      assert(
        sliced instanceof TargetTA,
        `is an instance of ${TargetTA.name}`
      );

      // Result typed array has the correct length with all elements set to zero.
      assert.compareArray(
        sliced,
        new TargetTA(N - startIndex),
        `${SourceTA.name} to ${TargetTA.name} with startIndex = ${startIndex}`
      );
    }
  }
}
}
main();

