let ta = new Int8Array(rab);

ta[0] = 11;
ta[1] = 22;

// Ensure typed array is correctly initialised.
assert.sameValue(ta.length, 2);
assert.sameValue(ta[0], 11);
assert.sameValue(ta[1], 22);

